cd ~/workspace && echo '' | base64 -d | gunzip > /tmp/CaixaEstoque.tsx && echo '' | base64 -d | gunzip > /tmp/TaxasMaquininha.tsx && node -e '
const fs=require("fs"),crypto=require("crypto"),h=f=>crypto.createHash("sha256").update(fs.readFileSync(f)).digest("hex").slice(0,16);
if(h("/tmp/CaixaEstoque.tsx")!=="ac609a2090f76804"||h("/tmp/TaxasMaquininha.tsx")!=="6536f1add8275afd"){console.log("❌ O comando chegou cortado. Copie de novo o bloco inteiro.");process.exit(1);}
const B="artifacts/fechamento/src/pages/";
if(!fs.existsSync(B+"TaxasMaquininha.tsx")||!fs.existsSync(B+"CaixaEstoque.tsx")){console.log("❌ Não achei as abas Taxas/Caixa. Nada foi alterado.");process.exit(1);}
const atual=fs.readFileSync(B+"TaxasMaquininha.tsx","utf8");
if(!atual.includes("INICIO_AUTOMATICO")&&!fs.existsSync(B+"TaxasMaquininha.tsx.antes-automatico"))fs.copyFileSync(B+"TaxasMaquininha.tsx",B+"TaxasMaquininha.tsx.antes-automatico");
fs.copyFileSync("/tmp/TaxasMaquininha.tsx",B+"TaxasMaquininha.tsx");
fs.copyFileSync("/tmp/CaixaEstoque.tsx",B+"CaixaEstoque.tsx");
console.log("✓ Aba Taxas automática instalada (a anterior ficou em TaxasMaquininha.tsx.antes-automatico)");
console.log("✓ Caixa atualizado (lucro das vendas e aparelhos vendidos sem custo)");
console.log("\n✅ PRONTO. Recarregue a pré-visualização.");
'
